{
  "summary": "Normalizes a string by removing leading and trailing whitespace and converting it to lowercase.",
  "input_schema": {
    "type": "object",
    "properties": {
      "name": {
        "type": "string",
        "description": "The input string to be normalized."
      }
    },
    "required": [
      "name"
    ],
    "additionalProperties": false
  },
  "functionalities": [
    "Removes leading and trailing whitespace from the input string",
    "Converts the string to lowercase",
    "Returns the normalized string"
  ]
}
